var longestCommonSubsequence = function(text1, text2) {
    const m = text1.length, n = text2.length;
    let prev = new Int32Array(n + 1);
    let curr = new Int32Array(n + 1);
    for (let i = 1; i <= m; ++i) {
        for (let j = 1; j <= n; ++j) {
            if (text1[i - 1] === text2[j - 1]) {
                curr[j] = 1 + prev[j - 1];
            } else {
                curr[j] = curr[j - 1] > prev[j] ? curr[j - 1] : prev[j];
            }
        }
        prev.set(curr);
    }
    return prev[n];
};
